    <script id="redirect-script" data-lang="de-de">
      function setCookieByLanguage (lang) {
        if(lang && lang.includes("-")) {
          Cookies.set('w4_country', lang.split('-')[1]);
          Cookies.set('w4_language', lang);
          Cookies.set('w4_local_language_slug', lang);
        } else {
          !Cookies.get('w4_country') && Cookies.set('w4_country', 'hq');
          Cookies.set('w4_language', lang);
        }
      }
      function redirectToPage (lang, suffix = '') {
        window.location.href = '/' + lang + '/' + suffix;
      }
      const redirectedSlugs = ['de-ch']
      const url = window.location.href
      let languageCode;
      try {
        languageCode = $("#redirect-script").data("lang");
        if(!languageCode) throw error
      } catch (error) {
        const urlCodes = window.location.pathname.match(/\/[a-z]{2}(-[a-z]{2})?\//)
        languageCode = (!urlCodes || urlCodes.length === 0) ? "de" : urlCodes[0].replace(/\//g, '')
      }
      const localPage = Cookies.get('w4_local_language_slug')
      var path = window.location.pathname.split('/')
      var savedLanguage = Cookies.get('w4_language');
      var w4Language = savedLanguage || languageCode;

      if(!savedLanguage || savedLanguage === 'undefined') {
        if(localPage && !path[2]) {
          setCookieByLanguage(localPage)
          if(w4Language != localPage && !path[2]) {
            redirectToPage(localPage, path.slice(2).join('/'))
          }
        } else {
          setCookieByLanguage(languageCode)
        }
      } else if(path[2] || (path[1] === 'en' && !path[2])){
        // allow user to visit page but cookie is not set
        // if(w4Language != path[1] && w4Language.split('-')[0] != path[1]) {
          // const lang = w4Language != path[1] ? w4Language : w4Language.split('-')[0];
        //   redirectToPage(w4Language.split('-')[0], path.slice(2).join('/'))
        // }
      } else if(localPage) {
        if(path[1] != localPage) {
          redirectToPage(localPage)
        }
      } else if(w4Language != path[1]) {
        if(path[1].split('-')[0] != w4Language && w4Language.split('-')[0] != path[1] && !redirectedSlugs.includes(path[1])) {
          redirectToPage(w4Language)
        } else if(!path[1].includes("-")) {
          redirectToPage(w4Language)
        } else {
          console.log(w4Language, localPage, path[1])
          setCookieByLanguage(path[1])
        }
      }
    </script>

