<!-- Header Keyboard Navigation Script -->
<script>
/**
 * Header Module - Keyboard Navigation Enhancement
 * Adds keyboard accessibility to existing header functionality
 */

(function() {
  'use strict';

  // Keyboard key codes
  const KEY_CODES = {
    ENTER: 13,
    ESCAPE: 27,
    ARROW_LEFT: 37,
    ARROW_UP: 38,
    ARROW_RIGHT: 39,
    ARROW_DOWN: 40,
    SPACE: 32,
    TAB: 9
  };

  // Header keyboard navigation class
  class HeaderKeyboardNavigation {
    constructor() {
      this.isDropdownOpen = false;
      this.currentDropdown = null;
      this.init();
    }

    init() {
      // Only setup keyboard navigation for desktop devices
      if (window.innerWidth >= 1200) {
        this.setupHubSpotMenus();
        this.preventContactButtonOpenClass();
        this.setupNavigationExitHandler();
      }

      // Listen for window resize to enable/disable desktop features
      window.addEventListener('resize', () => {
        if (window.innerWidth >= 1200) {
          this.setupHubSpotMenus();
          this.preventContactButtonOpenClass();
          this.setupNavigationExitHandler();
        }
      });
    }



    setupHubSpotMenus() {
      // Wait for HubSpot menus to be rendered - ONLY for the main navigation
      this.waitForHubSpotMenus();
    }

    waitForHubSpotMenus() {
      const checkMenus = () => {
        // ONLY target the main navigation menu, NOT the contact button
        const mainMenuWrapper = document.querySelector('#hs_cos_wrapper_multilingual-menu-new_ .hs-menu-wrapper');
        if (mainMenuWrapper) {
          // Triple-check: ensure this is ONLY the multilingual menu wrapper
          if (mainMenuWrapper.closest('#hs_cos_wrapper_multilingual-menu-new_') && 
              !mainMenuWrapper.closest('#contact_menu_wrapper') && 
              !mainMenuWrapper.closest('#contact_menu')) {
            this.enhanceHubSpotMenus();
          }
        } else {
          setTimeout(checkMenus, 200);
        }
      };
      setTimeout(checkMenus, 500);
    }

    enhanceHubSpotMenus() {
      // Only enhance menus on desktop devices
      if (window.innerWidth < 1200) {
        return;
      }

      // ONLY target the main navigation menu, NOT the contact button
      const mainMenuWrapper = document.querySelector('#hs_cos_wrapper_multilingual-menu-new_ .hs-menu-wrapper');
      if (!mainMenuWrapper) return;

      // Double-check: ensure this is ONLY the multilingual menu wrapper
      if (!mainMenuWrapper.closest('#hs_cos_wrapper_multilingual-menu-new_') || 
          mainMenuWrapper.closest('#contact_menu_wrapper') || 
          mainMenuWrapper.closest('#contact_menu')) {
        return; // Exit if not the right wrapper
      }

      // Get menu items ONLY from the main navigation, exclude contact button completely
      const menuItems = mainMenuWrapper.querySelectorAll('.hs-menu-item:not([data-contact-button])');

      menuItems.forEach((item, index) => {
        // Triple-check: ensure this is NOT the contact button wrapper
        if (item.closest('#contact_menu_wrapper') || item.closest('#contact_menu')) {
          return; // Skip contact button completely
        }

        const link = item.querySelector('a');
        if (link && !link.hasAttribute('data-keyboard-enhanced')) {
          link.setAttribute('tabindex', '0');
          link.setAttribute('data-keyboard-enhanced', 'true');

          const hasDropdown = item.querySelector('.hs-menu-children-wrapper') || 
                             item.classList.contains('hs-item-has-children') ||
                             item.querySelector('ul');



          if (hasDropdown) {
            link.setAttribute('aria-haspopup', 'true');
            link.setAttribute('aria-expanded', 'false');

            // Auto-open dropdown when tabbing to menu item
            link.addEventListener('focus', () => {
              // Just open the dropdown without interfering with HubSpot's behavior
              this.openDropdown(item);
            });

            link.addEventListener('keydown', (e) => {
              this.handleDropdownKeydown(e, item);
            });
          } else {
            link.addEventListener('keydown', (e) => {
              this.handleMenuItemKeydown(e, item);
            });
          }
        }
      });

      // Also enhance dropdown items for keyboard navigation
      this.enhanceDropdownItems();
    }

    enhanceDropdownItems() {
      // Only enhance dropdown items on desktop devices
      if (window.innerWidth < 1200) {
        return;
      }

      // ONLY target the main navigation menu, NOT the contact button
      const mainMenuWrapper = document.querySelector('#hs_cos_wrapper_multilingual-menu-new_ .hs-menu-wrapper');
      if (!mainMenuWrapper) return;

      // Double-check: ensure this is ONLY the multilingual menu wrapper
      if (!mainMenuWrapper.closest('#hs_cos_wrapper_multilingual-menu-new_') || 
          mainMenuWrapper.closest('#contact_menu_wrapper') || 
          mainMenuWrapper.closest('#contact_menu')) {
        return; // Exit if not the right wrapper
      }

      // Get dropdown items ONLY from the main navigation, exclude contact button completely
      const dropdownItems = mainMenuWrapper.querySelectorAll('.hs-menu-children-wrapper a:not([data-contact-button]), .hs-menu-children-wrapper ul a:not([data-contact-button])');

      dropdownItems.forEach((link) => {
        // Double-check: ensure this is NOT the contact button wrapper
        if (link.closest('#contact_menu_wrapper') || link.closest('#contact_menu')) {
          return; // Skip contact button completely
        }

        if (!link.hasAttribute('data-keyboard-enhanced')) {
          link.setAttribute('tabindex', '0');
          link.setAttribute('data-keyboard-enhanced', 'true');

          link.addEventListener('keydown', (e) => {
            this.handleDropdownItemKeydown(e, link);
          });
        }
      });
    }

    handleMenuItemKeydown(event, menuItem) {
      const link = menuItem.querySelector('a');

      switch (event.keyCode) {
        case KEY_CODES.ENTER:
        case KEY_CODES.SPACE:
          event.preventDefault();
          this.activateMenuItem(link);
          break;
        case KEY_CODES.ARROW_RIGHT:
          event.preventDefault();
          // Navigate to next main navigation item
          this.navigateToNextMenuItem(menuItem);
          break;
        case KEY_CODES.ARROW_LEFT:
          event.preventDefault();
          // Navigate to previous main navigation item
          this.navigateToPreviousMenuItem(menuItem);
          break;
        case KEY_CODES.ARROW_DOWN:
          event.preventDefault();
          // Check if this item has a dropdown and open it
          const hasDropdown = menuItem.querySelector('.hs-menu-children-wrapper') || 
                             menuItem.classList.contains('hs-item-has-children') ||
                             menuItem.querySelector('ul');
          if (hasDropdown) {
            this.openDropdown(menuItem);
          }
          break;
        case KEY_CODES.ESCAPE:
          event.preventDefault();
          this.closeAllDropdowns();
          break;
      }
    }

    handleDropdownKeydown(event, menuItem) {
      const link = menuItem.querySelector('a');

      switch (event.keyCode) {
        case KEY_CODES.ENTER:
        case KEY_CODES.SPACE:
          event.preventDefault();
          this.activateMenuItem(link);
          break;
        case KEY_CODES.ARROW_DOWN:
          event.preventDefault();
          // Navigate to first dropdown item
          if (this.isDropdownOpen && this.currentDropdown === menuItem) {
            this.navigateDropdownItems(menuItem, 'down');
          }
          break;
        case KEY_CODES.ARROW_UP:
          event.preventDefault();
          // Navigate to last dropdown item
          if (this.isDropdownOpen && this.currentDropdown === menuItem) {
            this.navigateDropdownItems(menuItem, 'up');
          }
          break;
        case KEY_CODES.ARROW_RIGHT:
          event.preventDefault();
          // Navigate to next main navigation item
          this.navigateToNextMenuItem(menuItem);
          break;
        case KEY_CODES.ARROW_LEFT:
          event.preventDefault();
          // Navigate to previous main navigation item
          this.navigateToPreviousMenuItem(menuItem);
          break;
        case KEY_CODES.ESCAPE:
          event.preventDefault();
          this.closeDropdown(menuItem);
          break;
      }
    }

    activateMenuItem(link) {
      // Simulate click on the link
      link.click();
    }

    navigateToNextMenuItem(currentItem) {
      const nextItem = currentItem.nextElementSibling;
      if (nextItem && nextItem.classList.contains('hs-menu-item')) {
        const nextLink = nextItem.querySelector('a');
        if (nextLink) {
          // Don't close current dropdown - just move to next item
          this.focusAndOpenDropdown(nextItem);
        }
      }
    }

    focusAndOpenDropdown(menuItem) {
      const link = menuItem.querySelector('a');
      if (link) {
        // Focus the item
        link.focus();

        // Auto-open dropdown if it has one (same as tab behavior)
        const hasDropdown = menuItem.querySelector('.hs-item-has-children') ||
                           menuItem.querySelector('.hs-menu-children-wrapper') || 
                           menuItem.querySelector('ul');
        if (hasDropdown) {
          this.openDropdown(menuItem);
        }
      }
    }

    navigateToPreviousMenuItem(currentItem) {
      const prevItem = currentItem.previousElementSibling;
      if (prevItem && prevItem.classList.contains('hs-menu-item')) {
        const prevLink = prevItem.querySelector('a');
        if (prevLink) {
          // Don't close current dropdown - just move to previous item
          this.focusAndOpenDropdown(prevItem);
        }
      }
    }

    navigateDropdownItems(menuItem, direction) {
      const dropdown = menuItem.querySelector('.hs-menu-children-wrapper') || 
                      menuItem.querySelector('ul');

      if (!dropdown) return;

      const dropdownItems = dropdown.querySelectorAll('a');
      if (dropdownItems.length === 0) return;

      // Find the currently focused item in this dropdown
      const currentFocusedItem = dropdown.querySelector('a:focus');
      let currentIndex = 0;

      if (currentFocusedItem) {
        currentIndex = Array.from(dropdownItems).indexOf(currentFocusedItem);
      }

      if (direction === 'down') {
        // Focus next dropdown item or first if at end
        const nextIndex = (currentIndex + 1) % dropdownItems.length;
        dropdownItems[nextIndex].focus();
      } else if (direction === 'up') {
        // Focus previous dropdown item or last if at beginning
        const prevIndex = currentIndex === 0 ? dropdownItems.length - 1 : currentIndex - 1;
        dropdownItems[prevIndex].focus();
      }
    }

    handleDropdownItemKeydown(event, link) {
      const dropdownItems = Array.from(link.closest('.hs-menu-children-wrapper, ul').querySelectorAll('a'));
      const currentIndex = dropdownItems.indexOf(link);

      switch (event.keyCode) {
        case KEY_CODES.ENTER:
        case KEY_CODES.SPACE:
          event.preventDefault();
          this.activateMenuItem(link);
          break;
        case KEY_CODES.ARROW_DOWN:
          event.preventDefault();
          // Navigate to next dropdown item
          const nextIndex = (currentIndex + 1) % dropdownItems.length;
          dropdownItems[nextIndex].focus();
          break;
        case KEY_CODES.ARROW_UP:
          event.preventDefault();
          // Navigate to previous dropdown item
          const prevIndex = currentIndex === 0 ? dropdownItems.length - 1 : currentIndex - 1;
          dropdownItems[prevIndex].focus();
          break;
        case KEY_CODES.ARROW_RIGHT:
          event.preventDefault();
          // Navigate to next main navigation item (not dropdown items)
          const parentMenuItem = link.closest('.hs-menu-item');
          if (parentMenuItem) {
            // Don't close the current dropdown when navigating - just move to next main item
            const nextItem = parentMenuItem.nextElementSibling;
            if (nextItem && nextItem.classList.contains('hs-menu-item')) {
              const nextLink = nextItem.querySelector('a');
              if (nextLink) {
                nextLink.focus();
                // Auto-open dropdown if it has one
                const hasDropdown = nextItem.querySelector('.hs-menu-children-wrapper') || 
                                   nextItem.classList.contains('hs-item-has-children') ||
                                   nextItem.querySelector('ul');
                if (hasDropdown) {
                  this.openDropdown(nextItem);
                }
              }
            }
          }
          break;
        case KEY_CODES.ARROW_LEFT:
          event.preventDefault();
          // Navigate to previous main navigation item (not dropdown items)
          const parentMenuItemLeft = link.closest('.hs-menu-item');
          if (parentMenuItemLeft) {
            // Don't close the current dropdown when navigating - just move to previous main item
            const prevItem = parentMenuItemLeft.previousElementSibling;
            if (prevItem && prevItem.classList.contains('hs-menu-item')) {
              const prevLink = prevItem.querySelector('a');
              if (prevLink) {
                prevLink.focus();
                // Auto-open dropdown if it has one
                const hasDropdown = prevItem.querySelector('.hs-menu-children-wrapper') || 
                                   prevItem.classList.contains('hs-item-has-children') ||
                                   prevItem.querySelector('ul');
                if (hasDropdown) {
                  this.openDropdown(prevItem);
                }
              }
            }
          }
          break;
        case KEY_CODES.TAB:
          event.preventDefault();
          // Tab should move to next main navigation item (same as Arrow Right)
          const parentMenuItemTab = link.closest('.hs-menu-item');
          if (parentMenuItemTab) {
            // Don't close the current dropdown when tabbing - just move to next main item
            const nextItem = parentMenuItemTab.nextElementSibling;
            if (nextItem && nextItem.classList.contains('hs-menu-item')) {
              const nextLink = nextItem.querySelector('a');
              if (nextLink) {
                nextLink.focus();
                // Auto-open dropdown if it has one
                const hasDropdown = nextItem.querySelector('.hs-menu-children-wrapper') || 
                                   nextItem.classList.contains('hs-item-has-children') ||
                                   nextItem.querySelector('ul');
                if (hasDropdown) {
                  this.openDropdown(nextItem);
                }
              }
            }
          }
          break;
        case KEY_CODES.ESCAPE:
          event.preventDefault();
          // Close dropdown and return focus to parent menu item
          const parentMenuItemEsc = link.closest('.hs-menu-item');
          if (parentMenuItemEsc) {
            this.closeDropdown(parentMenuItemEsc);
            const parentLink = parentMenuItemEsc.querySelector('a');
            if (parentLink) {
              parentLink.focus();
            }
          }
          break;
      }
    }



    openDropdown(menuItem) {
      // Only work on desktop devices
      if (window.innerWidth < 1200) {
        return;
      }

      // ONLY work with main navigation menu items, NOT contact button
      const mainMenuWrapper = document.querySelector('#hs_cos_wrapper_multilingual-menu-new_ .hs-menu-wrapper');
      if (!mainMenuWrapper || !mainMenuWrapper.contains(menuItem)) {
        return;
      }

      // Triple-check: ensure this is NOT the contact button wrapper
      if (menuItem.closest('#contact_menu_wrapper')) {
        return; // Block contact button completely
      }

      // Close any other open dropdown first
      if (this.currentDropdown && this.currentDropdown !== menuItem) {
        this.closeDropdown(this.currentDropdown);
      }

      // Add the open class and let HubSpot handle the rest
      if (!menuItem.classList.contains('open')) {
        menuItem.classList.add('open');

        const link = menuItem.querySelector('a');
        if (link) {
          link.setAttribute('aria-expanded', 'true');
        }

        this.isDropdownOpen = true;
        this.currentDropdown = menuItem;

        // For 3rd level navigation, ensure all nested dropdowns are visible
        this.ensureNestedDropdownsVisible(menuItem);

        // Focus the first dropdown item after a short delay
        setTimeout(() => {
          const dropdown = menuItem.querySelector('.hs-menu-children-wrapper') || 
                          menuItem.querySelector('ul');
          if (dropdown) {
            const firstDropdownItem = dropdown.querySelector('a');
            if (firstDropdownItem) {
              firstDropdownItem.focus();
            }
          }
        }, 100);
      }
    }

    closeDropdown(menuItem) {
      // Only work on desktop devices
      if (window.innerWidth < 1200) {
        return;
      }

      // ONLY work with main navigation menu items, NOT contact button
      const mainMenuWrapper = document.querySelector('#hs_cos_wrapper_multilingual-menu-new_ .hs-menu-wrapper');
      if (!mainMenuWrapper || !mainMenuWrapper.contains(menuItem)) {
        return;
      }

      // Triple-check: ensure this is NOT the contact button wrapper
      if (menuItem.closest('#contact_menu_wrapper')) {
        return; // Block contact button completely
      }

      // Just remove the open class and let HubSpot handle the rest
      menuItem.classList.remove('open');

      // Update ARIA attributes
      const link = menuItem.querySelector('a');
      if (link) {
        link.setAttribute('aria-expanded', 'false');
      }

      // Update state
      this.isDropdownOpen = false;
      this.currentDropdown = null;
    }

    closeAllDropdowns() {
      // Close all open dropdowns - ONLY for the main navigation
      const mainMenuWrapper = document.querySelector('#hs_cos_wrapper_multilingual-menu-new_ .hs-menu-wrapper');
      if (!mainMenuWrapper) return;

      const allMenuItems = mainMenuWrapper.querySelectorAll('.hs-menu-item');
      allMenuItems.forEach(item => {
        if (item.classList.contains('open')) {
          this.closeDropdown(item);
        }
      });
    }

    ensureNestedDropdownsVisible(menuItem) {
      // ONLY work with main navigation menu items, NOT contact button
      const mainMenuWrapper = document.querySelector('#hs_cos_wrapper_multilingual-menu-new_ .hs-menu-wrapper');
      if (!mainMenuWrapper || !mainMenuWrapper.contains(menuItem)) {
        return;
      }

      // For 3rd level navigation, ensure all nested dropdowns are visible
      const nestedDropdowns = menuItem.querySelectorAll('.hs-menu-children-wrapper, ul');
      nestedDropdowns.forEach(dropdown => {
        if (dropdown.style) {
          dropdown.style.display = 'block';
          dropdown.style.visibility = 'visible';
          dropdown.style.opacity = '1';
          dropdown.style.maxHeight = '4500px';
          dropdown.style.overflow = 'visible';
        }
      });

      // Add focus event listeners to ALL 2nd level items to handle 3rd level menus
      const secondLevelItems = menuItem.querySelectorAll('.hs-menu-depth-2 > a');
      secondLevelItems.forEach(secondLevelLink => {
        if (!secondLevelLink.hasAttribute('data-3rd-level-enhanced')) {
          secondLevelLink.setAttribute('data-3rd-level-enhanced', 'true');

          // Simple focus event to handle 3rd level menu behavior
          secondLevelLink.addEventListener('focus', (e) => {
            // Check if this 2nd level item has children (3rd level menu)
            const hasChildren = secondLevelLink.closest('.hs-menu-depth-2').classList.contains('hs-item-has-children');

            if (hasChildren) {
              // This 2nd level item HAS 3rd level children - open its menu
              const parentItem = secondLevelLink.closest('.hs-menu-depth-2');
              const thirdLevelMenu = parentItem.querySelector('ul');

              // Close all other 3rd level menus first
              document.querySelectorAll('.hs-menu-depth-2.hs-item-has-children').forEach(item => {
                if (item !== parentItem) {
                  item.classList.remove('open');
                  const menu = item.querySelector('ul');
                  if (menu) {
                    menu.style.display = 'none';
                    menu.style.visibility = 'hidden';
                    menu.style.opacity = '0';
                  }
                }
              });

              // Open this 2nd level item's 3rd level menu
              parentItem.classList.add('open');
              if (thirdLevelMenu) {
                thirdLevelMenu.style.display = 'block';
                thirdLevelMenu.style.visibility = 'visible';
                thirdLevelMenu.style.opacity = '1';
              }
            } else {
              // This 2nd level item has NO 3rd level children - close all 3rd level menus
              document.querySelectorAll('.hs-menu-depth-2.hs-item-has-children').forEach(item => {
                item.classList.remove('open');
                const menu = item.querySelector('ul');
                if (menu) {
                  menu.style.display = 'none';
                  menu.style.visibility = 'hidden';
                  menu.style.opacity = '0';
                }
              });
            }
          });
        }
      });
    }


    closeOther3rdLevelMenus(currentSecondLevelLink) {
      // ONLY work with main navigation menu items, NOT contact button
      const mainMenuWrapper = document.querySelector('#hs_cos_wrapper_multilingual-menu-new_ .hs-menu-wrapper');
      if (!mainMenuWrapper || !mainMenuWrapper.contains(currentSecondLevelLink)) {
        return;
      }

      // Close ALL 3rd level menus across the entire navigation
      this.closeAll3rdLevelMenus();
    }

    showSpecific3rdLevelMenu(secondLevelLink) {
      // ONLY work with main navigation menu items, NOT contact button
      const mainMenuWrapper = document.querySelector('#hs_cos_wrapper_multilingual-menu-new_ .hs-menu-wrapper');
      if (!mainMenuWrapper || !mainMenuWrapper.contains(secondLevelLink)) {
        return;
      }

      // Show only the 3rd level menu for this specific 2nd level item
      const thirdLevelMenu = secondLevelLink.nextElementSibling;
      if (thirdLevelMenu && thirdLevelMenu.tagName === 'UL') {
        thirdLevelMenu.style.display = 'block';
        thirdLevelMenu.style.visibility = 'visible';
        thirdLevelMenu.style.opacity = '1';
      }
    }


    preventContactButtonOpenClass() {
      // Actively prevent the contact button from getting the 'open' class
      const contactButton = document.querySelector('#contact_menu_wrapper .hs-menu-item a');
      if (contactButton) {
        // Remove any existing 'open' class
        contactButton.classList.remove('open');

        // Set up a MutationObserver to watch for class changes
        const observer = new MutationObserver((mutations) => {
          mutations.forEach((mutation) => {
            if (mutation.type === 'attributes' && mutation.attributeName === 'class') {
              // If 'open' class is added, remove it immediately
              if (contactButton.classList.contains('open')) {
                contactButton.classList.remove('open');
              }
            }
          });
        });

        // Start observing the contact button for class changes
        observer.observe(contactButton, {
          attributes: true,
          attributeFilter: ['class']
        });

        // Also prevent the parent li from getting 'open' class
        const contactMenuItem = contactButton.closest('.hs-menu-item');
        if (contactMenuItem) {
          contactMenuItem.classList.remove('open');

          const liObserver = new MutationObserver((mutations) => {
            mutations.forEach((mutation) => {
              if (mutation.type === 'attributes' && mutation.attributeName === 'class') {
                // If 'open' class is added to li, remove it immediately
                if (contactMenuItem.classList.contains('open')) {
                  contactMenuItem.classList.remove('open');
                }
              }
            });
          });

          liObserver.observe(contactMenuItem, {
            attributes: true,
            attributeFilter: ['class']
          });
        }
      }
    }

    setupNavigationExitHandler() {
      // Close dropdowns when user tabs out of the navigation
      document.addEventListener('focusin', (event) => {
        const mainMenuWrapper = document.querySelector('#hs_cos_wrapper_multilingual-menu-new_ .hs-menu-wrapper');
        if (!mainMenuWrapper) return;

        // Check if the focused element is outside the main navigation
        if (!mainMenuWrapper.contains(event.target)) {
          // Close all open dropdowns
          this.closeAllDropdowns();
        }
      });

      // Also close dropdowns when clicking outside the navigation
      document.addEventListener('click', (event) => {
        const mainMenuWrapper = document.querySelector('#hs_cos_wrapper_multilingual-menu-new_ .hs-menu-wrapper');
        if (!mainMenuWrapper) return;

        // Check if the clicked element is outside the main navigation
        if (!mainMenuWrapper.contains(event.target)) {
          // Close all open dropdowns
          this.closeAllDropdowns();
        }
      });
    }




  }

  // Initialize when DOM is ready
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', () => {
      new HeaderKeyboardNavigation();
    });
  } else {
    new HeaderKeyboardNavigation();
  }

})();
</script></div>



