<script>
// check if contact form exist on the page, if yes, don't display this form
  if ($('div.rob-form').length == 0) {
      var apiEndpoint = "http://go.robatech.com/l/837263/2021-02-04/dcxw8";
      var fieldsMappingJson = '{"rob_gender": "salutation","firstname": "first_name","lastname": "last_name","company": "company","email": "email","rob_country": "country","message": "message","privacy_policy": "privacy_policy"}';
      var fieldsMapping = JSON.parse(fieldsMappingJson);
      var formId = "99983c5a-1db7-4ede-bf62-0eeb436aa7f3";
      var formFields = Object.keys(fieldsMapping);

      window.addEventListener('message', function(event) {
        if(event.data.type === 'hsFormCallback' && event.data.eventName === 'onFormSubmit') {
          if (event.data.id == formId) {
            var submittedData = event.data.data;
            var postData = {
              "privacy_policy": true
            };

            formFields.forEach((key, index) => {
              var mappedKey = fieldsMapping[key];

              var formFieldObject = submittedData.filter((field) => field.name === key);
              if (formFieldObject.length > 0 && formFieldObject[0].value) {
                postData[mappedKey] = formFieldObject[0].value;
              }
            });

            $.ajax({
              url: apiEndpoint,
              data: postData,
              type: 'POST',
              crossDomain: true,        // important for CORS
              dataType: 'jsonp',
              success: function(response) { },
              error: function(error) { console.log('API Error:', error); }
            });
          }
        }
  });
} else {
  // disable sidebar formFieldObject
  $('.sidepanel').hide()
}
</script></div>

